public class Factorial {
    public static void main(String[] args) {
        int num = 5;
        int fact = 1;
        for(int i=1;i<=num;i++) {
            fact *= i;
        }
        System.out.println(fact);
    }
}

public class ReverseNumber {
    public static void main(String[] args) {
        int num = 1234;
        int rev = 0;
        while(num > 0) {
            rev = rev * 10 + num % 10;
            num /= 10;
        }
        System.out.println(rev);
    }
}

